function Button({ text = 'Click me', variant = 'primary' }) {
  return <button className={`btn btn-${variant}`}>{text}</button>;
}

// Uses defaults
<Button />

// Overrides
<Button text="Submit" variant="success" />

function Card({ title, children }) {
  return (
    <div className="card">
      {title && <h2 className="card-title">{title}</h2>}
      <div className="card-body">{children}</div>
    </div>
  );
}

// Usage
<Card title="Welcome">
  <p>This content goes inside the card body.</p>
  <button>Action</button>
</Card>

const user = {
  firstName: 'Alice',
  lastName: 'Smith',
  email: 'alice@example.com',
  role: 'admin'
};

// Without spread
<UserProfile
  firstName={user.firstName}
  lastName={user.lastName}
  email={user.email}
  role={user.role}
/>

// With spread
<UserProfile {...user} />

function MouseTracker({ render }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const move = (e) => setPos({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', move);
    return () => window.removeEventListener('mousemove', move);
  }, []);

  return <div>{render(pos)}</div>;
}

// Usage — parent decides what to render
<MouseTracker
  render={({ x, y }) => (
    <p>Mouse at ({x}, {y})</p>
  )}
/>
